/// history_preview — variable length, ≤ 244 B on the wire.
/// Explicit length fields are derived from the list/byte lengths.
class HistoryPreview {
  HistoryPreview({
    this.ver = 1,
    this.probeIndex = 0,
    this.bucketMin = 0,
    List<int>? values,
  }) : values = values ?? const <int>[];

  static const int maxSize = 244;

  final int ver;
  final int probeIndex;

  /// nominal 1
  final int bucketMin;

  /// tenths °F
  final List<int> values;

  /// null for sentinel (detached/invalid) entries.
  List<int?> get valuesNullable => [
    for (final v in values)
      if (v == tempDetached || v == tempInvalid) null else v,
  ];

  /// Serializes to wire bytes. Throws [ArgumentError] if a variable
  /// field exceeds its declared max.
  Uint8List pack() {
    if (values.length > 120) {
      throw ArgumentError('values exceeds 120 elements');
    }
    final out = BytesBuilder();
    out.addByte(ver & 0xFF);
    out.addByte(probeIndex & 0xFF);
    out.addByte(values.length);
    out.addByte(bucketMin & 0xFF);
    for (final v in values) {
      out.addByte(v & 0xFF);
      out.addByte((v >> 8) & 0xFF); // little-endian i16
    }
    return out.toBytes();
  }

  /// Parses wire bytes. Throws [FormatException] on truncation or
  /// out-of-range lengths.
  static HistoryPreview unpack(Uint8List buf) {
    final bd = ByteData.sublistView(buf);
    var off = 0;
    void need(int n) {
      if (off + n > buf.length) {
        throw FormatException('history_preview: truncated at byte $off');
      }
    }

    need(1);
    final verV = bd.getUint8(off);
    off += 1;
    need(1);
    final probeIndexV = bd.getUint8(off);
    off += 1;
    need(1);
    final countV = bd.getUint8(off);
    off += 1;
    need(1);
    final bucketMinV = bd.getUint8(off);
    off += 1;
    if (countV > 120) {
      throw FormatException('history_preview.values: length over max');
    }
    need(countV * 2);
    final valuesV = <int>[
      for (var i = 0; i < countV; i++) bd.getInt16(off + i * 2, Endian.little),
    ];
    off += countV * 2;
    return HistoryPreview(
      ver: verV,
      probeIndex: probeIndexV,
      bucketMin: bucketMinV,
      values: valuesV,
    );
  }
}

/// set_time — fixed 10 B. (device_control body)
class CtrlSetTime {
  CtrlSetTime({this.unixMs = 0, this.tzOffsetMin = 0});

  static const int size = 10;

  final int unixMs;
  final int tzOffsetMin;

  /// Parses 10 wire bytes at [offset]. Never rejects on version;
  /// check [crcOk] after decoding.
  factory CtrlSetTime.decode(Uint8List buf, [int offset = 0]) {
    final bd = ByteData.sublistView(buf, offset, offset + size);
    return CtrlSetTime(
      unixMs: bd.getUint64(0, Endian.little),
      tzOffsetMin: bd.getInt16(8, Endian.little),
    );
  }

  /// Serializes to 10 wire bytes.
  Uint8List encode() {
    final out = Uint8List(size);
    final bd = ByteData.sublistView(out);
    bd.setUint64(0, unixMs, Endian.little);
    bd.setInt16(8, tzOffsetMin, Endian.little);
    return out;
  }
}

